import java.util.*; public class GraphRepresentationBFS { public List<Integer> bfsOfGraph(int v, List<List<Integer>> adj) { List<Integer> bfsRes = new ArrayList<>(); boolean[] vis = new boolean[v]; Queue<Integer> q = new LinkedList<>(); q.add(0); vis[0] = true; while (!q.isEmpty()) { int node = q.poll(); bfsRes.add(node); for (int neighbor : adj.get(node)) { if (!vis[neighbor]) { vis[neighbor] = true; q.add(neighbor); } } } return bfsRes; } }
